#!/usr/bin/env python3
from pathlib import Path
import base64
import shutil
import datetime
import subprocess

PAYLOADS = {'package.json': '', 'server.js': '', 'src/cloneEngine.js': '', 'public/clone-runtime.js': '', 'public/clone-runtime.css': '', 'public/index.html': '', 'README.md': '', 'start.bat': ''}

root = Path.cwd()

if not (root / "server.js").exists() or not (root / "package.json").exists():
    print("")
    print("ERRO: coloque este arquivo DENTRO da pasta page-clone-engine.")
    print("")
    input("Pressione Enter para fechar...")
    raise SystemExit(1)

backup = root / ("backup-v3-" + datetime.datetime.now().strftime("%Y%m%d-%H%M%S"))
backup.mkdir(parents=True, exist_ok=True)

print("")
print("============================================")
print("       PAGE CLONE ENGINE v0.4")
print("============================================")
print("")
print("Fazendo backup em:", backup)

for rel in PAYLOADS:
    src = root / rel
    if src.exists():
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)

print("Aplicando correções v0.4...")

for rel, encoded in PAYLOADS.items():
    dst = root / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_bytes(base64.b64decode(encoded))

print("Projetos antigos em data/projects foram preservados.")
print("")
print("Ajustando dependências...")
result = subprocess.run(["npm", "install"], shell=True)

if result.returncode != 0:
    print("npm install falhou.")
    input("Pressione Enter para fechar...")
    raise SystemExit(result.returncode)

print("")
print("Testando arquivos JavaScript...")

for rel in [
    "server.js",
    "src/cloneEngine.js",
    "public/clone-runtime.js"
]:
    result = subprocess.run(["node", "--check", rel], shell=True)
    if result.returncode != 0:
        print("Erro de sintaxe em:", rel)
        input("Pressione Enter para fechar...")
        raise SystemExit(result.returncode)

print("")
print("============================================")
print("        ATUALIZACAO CONCLUIDA")
print("============================================")
print("")
print("CORRECAO PRINCIPAL:")
print("- clone-config agora carrega do localhost")
print("- mobile redireciona imediatamente para mobile.html")
print("- titulo/hero/miniaturas sao marcados antes de remover JS")
print("- imagens lazy sao congeladas no currentSrc")
print("- skeletons antigos sao neutralizados")
print("")
print("Agora:")
print("1. Feche o servidor antigo.")
print("2. Execute start.bat.")
print("3. CRIE UM CLONE NOVO para testar.")
print("")
input("Pressione Enter para fechar...")
